const app=document.querySelector('#app');
const homeMarkup=app.innerHTML;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let active='全部',query='';
const detailExtras={
'forbidden-city':['东城或王府井','北京烤鸭、炸酱面、豆汁焦圈','地铁 1 号线至天安门东/西站后步行；结束参观后从神武门离场。'],
'great-wall':['德胜门沿线或八达岭镇','春饼、铜锅涮肉、延庆火勺','可乘市郊铁路或正规景区巴士；自驾需提前确认停车与预约。'],
'terracotta-army':['钟楼、永宁门或临潼','肉夹馍、凉皮、羊肉泡馍','从西安市区乘正规旅游专线或地铁换乘公交，预留约一小时以上。'],
'west-lake':['湖滨、北山街或南山路','西湖醋鱼、龙井虾仁、片儿川','优先地铁与公交到达湖滨，湖区内步行、骑行和游船组合最方便。'],
'huangshan':['汤口镇或山顶酒店','臭鳜鱼、毛豆腐、笋干烧肉','抵达黄山北站后换乘至汤口，再乘景区交通到索道站。'],
'zhangjiajie':['武陵源标志门附近','三下锅、土家腊肉、葛根粉','从张家界西站或荷花机场前往武陵源，入园后以环保车连接各片区。'],
'jiuzhaigou':['沟口或漳扎镇','牦牛肉、青稞饼、酸奶','可从成都转乘航班或长途客运抵达，沟内按观光车调度游览。'],
'li-river':['桂林两江四湖或阳朔西街外围','桂林米粉、啤酒鱼、荔浦芋扣肉','桂林码头乘游船前往阳朔；竹筏游览需确认区段与接驳。'],
'potala-palace':['布达拉宫周边或八廓街外围','藏面、甜茶、牦牛肉','拉萨市区可乘公交或出租车抵达，预约时段前预留安检与步行时间。'],
'yalong-bay':['亚龙湾沿海酒店区或吉阳','清补凉、海南粉、椰子鸡','从三亚机场或高铁站乘巴士、出租车抵达，湾内短途以步行和接驳为主。']};
function favorites(){try{return JSON.parse(localStorage.getItem('shanhe-favorites')||'[]')}catch{return[]}}
function toggleFavorite(id){const set=new Set(favorites());set.has(id)?set.delete(id):set.add(id);localStorage.setItem('shanhe-favorites',JSON.stringify([...set]));route()}
function card(d){return `<article class="destination-card" style="--card-a:${d.colors[0]};--card-b:${d.colors[1]}"><div class="card-art" data-mark="${d.mark}"><span class="card-index">NO. ${String(DESTINATIONS.indexOf(d)+1).padStart(2,'0')}</span><span class="card-icon" aria-hidden="true">${d.icon}</span></div><div class="card-body"><div class="card-meta"><span>⌖ ${d.city}</span><span>${d.season} · ${d.duration}</span></div><h3>${d.name}</h3><p>${d.summary}</p><div class="tag-row">${d.theme.map(t=>`<span class="tag">${t}</span>`).join('')}<span class="tag">${d.level}</span></div></div><a class="card-link" href="#attraction/${d.id}" aria-label="查看${d.name}攻略"></a></article>`}
function renderGrid(){const grid=$('#destination-grid');if(!grid)return;const list=DESTINATIONS.filter(d=>(active==='全部'||d.theme.includes(active))&&`${d.name}${d.city}${d.region}${d.theme.join('')}${d.summary}`.toLowerCase().includes(query.toLowerCase()));grid.innerHTML=list.length?list.map(card).join(''):`<div class="empty-state"><span class="empty-icon">⌕</span><h3>没有找到匹配的目的地</h3><p>换一个关键词或清空筛选条件试试。</p><button class="primary-button" id="reset-search">查看全部</button></div>`;$('#reset-search')?.addEventListener('click',()=>{query='';active='全部';renderHome()})}
function bindHome(){$$('.filter').forEach(btn=>btn.addEventListener('click',()=>{$('.filter.active')?.classList.remove('active');btn.classList.add('active');active=btn.dataset.filter;renderGrid()}));$('.search-shell')?.addEventListener('submit',e=>{e.preventDefault();query=$('#search').value.trim();location.hash='explore';renderGrid()});$('#search')?.addEventListener('input',e=>{query=e.target.value.trim();renderGrid()});renderGrid()}
function setTitle(t){document.title=t}function renderHome(){app.innerHTML=homeMarkup;bindHome();setTitle('山河志 · 中国旅行攻略')}
function detailImage(d){return d.theme.includes('历史人文')?'assets/palace-walls.png':'assets/mountain-lake.png'}
function renderDetail(d){const ex=detailExtras[d.id],saved=favorites().includes(d.id),others=DESTINATIONS.filter(x=>x.id!==d.id&&(x.region===d.region||x.theme.some(t=>d.theme.includes(t)))).slice(0,3);app.innerHTML=`
<article class="detail-page"><section class="detail-hero" style="--detail-a:${d.colors[0]};--detail-b:${d.colors[1]}"><img src="${detailImage(d)}" alt="${d.name}攻略氛围图"><div class="detail-shade"></div><div class="detail-heading"><a class="back-link" href="#home">← 返回目的地</a><p class="eyebrow">${d.region} · ${d.city}</p><h1>${d.name}</h1><p>${d.summary}</p><div class="detail-actions"><button class="favorite-button ${saved?'saved':''}" data-favorite="${d.id}">${saved?'♥ 已收藏':'♡ 收藏攻略'}</button><button class="share-button" id="share-button">↗ 分享</button></div></div></section>
<section class="quick-facts"><div><span>建议时长</span><strong>${d.duration}</strong></div><div><span>最佳季节</span><strong>${d.season}</strong></div><div><span>体力强度</span><strong>${d.level}</strong></div><div><span>推荐主题</span><strong>${d.theme[0]}</strong></div></section>
<div class="detail-layout"><aside class="detail-nav"><strong>攻略目录</strong><a href="#overview">为什么值得去</a><a href="#route">推荐路线</a><a href="#transport">到达方式</a><a href="#practical">行前信息</a><a href="#stay">住在哪里</a><a href="#nearby">继续探索</a></aside><div class="detail-content">
<section id="overview" class="content-section"><p class="section-kicker">DESTINATION</p><h2>为什么值得去</h2><p class="lead">${d.summary}</p><p>${d.name}不只是一个打卡点。把核心景观、在地故事与从容的游览节奏放在一起，才能感受到它真正的魅力。首次到访建议围绕经典线路安排，再根据天气、体力和兴趣做取舍。</p><div class="highlight-grid">${d.highlights.map((h,i)=>`<div><span>0${i+1}</span><strong>${h}</strong><p>${i===0?'最具代表性的核心景观，建议优先安排。':i===1?'适合放慢脚步观察细节与光影。':'为整段旅程补充更完整的在地体验。'}</p></div>`).join('')}</div></section>
<section id="route" class="content-section route-section"><p class="section-kicker">ROUTE</p><h2>一条好走的经典路线</h2><div class="route-summary"><strong>${d.duration} · ${d.level}强度</strong><span>建议上午尽早出发</span></div><ol class="route-line">${d.route.map((p,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><strong>${p}</strong><p>${i===0?'从这里开始，预留入园与安检时间。':i===d.route.length-1?'在此结束主线游览，按交通时间从容返程。':'停留约 30–60 分钟，视人流与体力调整。'}</p></div></li>`).join('')}</ol><div class="route-alternative"><span>轻松路线</span><p>保留前半段三个核心节点，优先使用观光车、索道或游船，午后提前返程。适合亲子家庭、长者与希望控制步行量的旅行者。</p></div></section>
<section id="transport" class="content-section"><p class="section-kicker">ARRIVAL</p><h2>怎么到达</h2><div class="transport-card"><div class="transport-icon">⌖</div><div><h3>公共交通优先</h3><p>${ex[2]}</p><div class="compare-row"><span><b>优点</b>省心、停车压力小</span><span><b>提醒</b>返程班次提前确认</span></div></div></div><p class="notice">交通班次与运行时间会调整，出发前请通过当地交通及景区官方渠道再次确认。</p></section>
<section id="practical" class="content-section"><p class="section-kicker">BEFORE YOU GO</p><h2>出发前要知道</h2><div class="practical-grid"><div><span>预约与门票</span><h3>实名预约优先</h3><p>热门日期尽早预约，携带下单时使用的有效证件。票价、优惠政策及入园时段以官方发布为准。</p></div><div><span>季节与天气</span><h3>${d.season}体验更佳</h3><p>山地与高原昼夜温差明显；海滨注意强紫外线和台风信息，雨季准备轻便雨具。</p></div><div><span>行李清单</span><h3>轻装、好走最重要</h3><p>防滑鞋、饮水、防晒用品、充电设备和少量应急药品。景区内遵守环保要求。</p></div><div><span>特别提醒</span><h3>把安全放在体验前</h3><p>${d.tips}</p></div></div><div class="verified">信息核验提示：开放时间、预约与价格属于动态信息，请在出发前查看景区官方渠道。</div></section>
<section id="stay" class="content-section"><p class="section-kicker">STAY & TASTE</p><h2>住在哪里，吃些什么</h2><div class="stay-split"><div><h3>${ex[0]}</h3><p>优先选择公共交通方便、评价稳定的区域。节假日和旺季建议提前预订，具体价格与房态以平台实时信息为准。</p></div><div><h3>在地风味</h3><p>${ex[1]}</p><p class="muted">留意个人饮食禁忌，明码标价后再消费。</p></div></div><div class="budget"><div><span>经济型参考</span><strong>¥400–800 / 人·日</strong></div><div><span>舒适型参考</span><strong>¥900–1600 / 人·日</strong></div><p>预算为门票、当地交通、住宿与餐饮的粗略区间，不含出发地往返大交通。</p></div></section>
<section id="nearby" class="content-section"><p class="section-kicker">KEEP EXPLORING</p><h2>继续探索</h2><div class="nearby-grid">${others.map(card).join('')}</div></section></div></div></article>`;
$$('[data-favorite]').forEach(b=>b.addEventListener('click',()=>toggleFavorite(b.dataset.favorite)));$('#share-button').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);$('#share-button').textContent='✓ 链接已复制'}catch{$('#share-button').textContent='请复制地址栏链接'}});setTitle(`${d.name}旅行攻略 · 山河志`);window.scrollTo(0,0)}
function renderFavorites(){const ids=favorites(),list=DESTINATIONS.filter(d=>ids.includes(d.id));app.innerHTML=`<section class="collection-page"><p class="eyebrow dark">MY COLLECTION</p><h1>我的收藏</h1><p>把想去的地方放在一起，下一段旅程就从这里开始。</p><div class="destination-grid">${list.length?list.map(card).join(''):`<div class="empty-state"><span class="empty-icon">♡</span><h3>还没有收藏目的地</h3><p>浏览十大景点，点击“收藏攻略”即可保存到当前设备。</p><a class="primary-button inline" href="#home">去发现景点</a></div>`}</div></section>`;setTitle('我的收藏 · 山河志');window.scrollTo(0,0)}
function renderNotFound(){app.innerHTML=`<section class="not-found"><span>404</span><h1>这条路暂时走不通</h1><p>目的地可能已更名，返回首页重新出发吧。</p><a class="primary-button inline" href="#home">返回首页</a></section>`;setTitle('页面未找到 · 山河志')}
function route(){const hash=location.hash.slice(1)||'home';if(hash.startsWith('attraction/')){const d=DESTINATIONS.find(x=>x.id===hash.split('/')[1]);d?renderDetail(d):renderNotFound()}else if(hash==='favorites')renderFavorites();else renderHome()}
$('.menu-button').addEventListener('click',e=>{const nav=$('.site-header nav');nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',nav.classList.contains('open'))});window.addEventListener('hashchange',route);route();
